import { HtmlConf } from '@droid/android';
import { HtmlConfUI } from './HtmlConfUI';

export interface HtmlConfSectionProps {
  htmlConf?: HtmlConf;
}

/**
 * HtmlConfSection - HTML 内容编辑区域
 *
 * 编辑字段：
 * - url: 内容 URL
 * - html: 内嵌 HTML 代码
 * - jsBridgeName: 注入的 JS Bridge 名称
 * - webViewJsName: WebView JS 类型
 * - javaRunnerId: Java Runner ID
 * - webViewJsParams: WebView JS 参数
 * - webViewConf: WebView 配置
 */
export function HtmlConfSection({ htmlConf }: HtmlConfSectionProps) {
  if (!htmlConf) {
    return null;
  }

  console.log('HtmlConfSection: render htmlConf:', htmlConf);

  return <HtmlConfUI htmlConf={htmlConf} />;
}
